using Diten.DecisionIntelligenceService.Persistence.Modules.OutcomeTracking.Manifests;using Xunit;
public class ManifestTests
{
 static string Root(){var d=new DirectoryInfo(AppContext.BaseDirectory);while(d is not null&&!File.Exists(Path.Combine(d.FullName,"AGENTS.md")))d=d.Parent;return d!.FullName;}
 [Fact]public void Manifest_is_exact_tenant_first_and_never_ttl(){string[] names=["diten_di_outcomes","diten_di_outcome_versions","diten_di_outcome_metrics","diten_di_outcome_metric_versions","diten_di_qualitative_scales","diten_di_qualitative_scale_versions","diten_di_outcome_measurements","diten_di_decision_outcome_links","diten_di_idempotency_receipts","diten_di_audit_intents","diten_di_outbox_messages"];Assert.Equal(names,OutcomeTrackingMongoOwnershipManifest.Collections);Assert.Equal(16,OutcomeTrackingMongoOwnershipManifest.Indexes.Length);Assert.All(OutcomeTrackingMongoOwnershipManifest.Indexes,x=>{Assert.Equal("TenantId",x.Keys[0]);Assert.False(x.IsTtl);});}
 [Fact]public void Source_has_no_projection_persistence_delete_or_foreign_dependency(){var src=Path.Combine(Root(),"services/Diten.DecisionIntelligenceService/src");var text=string.Join("\n",Directory.GetFiles(src,"*",SearchOption.AllDirectories).Where(x=>!x.Contains("/bin/")&&!x.Contains("/obj/")).Select(File.ReadAllText));foreach(var token in new[]{"ProjectionRepository","ProjectionCollection","projection_checkpoint","ExpireAfter","DeleteAsync","SoftDelete","BulkDelete","Purge","Diten.FpaService","Diten.EnterpriseStrategyService","MongoClient","MassTransit","RabbitMQ"})Assert.DoesNotContain(token,text,StringComparison.Ordinal);}
}
